 sealed class SurfaceGrid {
  const float Cell=.025f;
  public readonly Dictionary<Vector3Int,List<int>> cells=new Dictionary<Vector3Int,List<int>>();
  public static Vector3Int Index(Vector3 p)=>new Vector3Int(Mathf.FloorToInt(p.x/Cell),Mathf.FloorToInt(p.y/Cell),Mathf.FloorToInt(p.z/Cell));
  public SurfaceGrid(Vector3[] p,int[] triangles){for(int j=0;j<triangles.Length;j+=3){var lo=Index(Vector3.Min(p[triangles[j]],Vector3.Min(p[triangles[j+1]],p[triangles[j+2]])));var hi=Index(Vector3.Max(p[triangles[j]],Vector3.Max(p[triangles[j+1]],p[triangles[j+2]])));for(int x=lo.x;x<=hi.x;x++)for(int y=lo.y;y<=hi.y;y++)for(int z=lo.z;z<=hi.z;z++){var key=new Vector3Int(x,y,z);if(!cells.TryGetValue(key,out var list))cells[key]=list=new List<int>();list.Add(j);}}}
 }
 static readonly Dictionary<(Vector3[],int[]),SurfaceGrid> surfaceGrids=new Dictionary<(Vector3[],int[]),SurfaceGrid>();
